1: import { createServer } from "node:http";
2: import { join } from "node:path";
3: import { fileURLToPath } from "node:url";
4: 
5: import { readJsonBody, sendJson, serveStatic } from "./lib/http.mjs";
6: import { searchProducts } from "./lib/search-index.mjs";
7: 
8: const PORT = process.env.PORT ?? 4173;
9: const PUBLIC_DIR = join(fileURLToPath(new URL(".", import.meta.url)), "public");
10: 
11: // The six items on the home page. The full searchable catalog lives in
12: // lib/catalog.mjs and is only reachable through /api/search.
13: const PRODUCTS = [
14:   { id: "mug-classic", name: "Classic Mug", price: 1400, emoji: "☕" },
15:   { id: "tee-logo", name: "Logo Tee", price: 2500, emoji: "��" },
16:   { id: "cap-canvas", name: "Canvas Cap", price: 1900, emoji: "��" },
17:   { id: "tote-daily", name: "Daily Tote", price: 2200, emoji: "��" },
18:   { id: "bottle-steel", name: "Steel Bottle", price: 2800, emoji: "��" },
19:   { id: "notebook-dot", name: "Dot Notebook", price: 1200, emoji: "��" },
20: ];
21: 
22: const COUPONS = {
23:   SAVE10: { code: "SAVE10", pct: 10 },
24:   WELCOME5: { code: "WELCOME5", pct: 5 },
25: };
26: 
27: // Single in-memory cart — this is a demo storefront, no sessions.
28: const cart = {
29:   items: [],
30:   coupons: [],
31: };
32: 
33: function cartSubtotal() {
34:   return cart.items.reduce((sum, item) => {
35:     const product = PRODUCTS.find((p) => p.id === item.productId);
36:     return sum + product.price * item.quantity;
37:   }, 0);
38: }
39: 
40: function cartDiscount() {
41:   const subtotal = cartSubtotal();
42:   return cart.coupons.reduce(
43:     (sum, coupon) => sum + Math.round((subtotal * coupon.pct) / 100),
44:     0,
45:   );
46: }
47: 
48: function serializeCart() {
49:   const subtotal = cartSubtotal();
50:   const discount = cartDiscount();
51:   return {
52:     items: cart.items.map((item) => ({
53:       ...item,
54:       product: PRODUCTS.find((p) => p.id === item.productId),
55:     })),
56:     coupons: cart.coupons.map((c) => c.code),
57:     subtotal,
58:     discount,
59:     total: subtotal - discount,
60:   };
61: }
62: 
63: function applyCoupon(code) {
64:   const coupon = COUPONS[code?.toUpperCase()];
65:   if (!coupon) {
66:     return { status: 400, body: { error: "Invalid coupon code" } };
67:   }
68: 
69:   const existing = cart.coupons.find((c) => c.code === coupon.code);
70:   if (existing) {
71:     // Re-applying just refreshes the applied timestamp.
72:     existing.appliedAt.push(Date.now());
73:     return { status: 200, body: { cart: serializeCart() } };
74:   }
75: 
76:   cart.coupons.push({ ...coupon, appliedAt: Date.now() });
77:   return { status: 200, body: { cart: serializeCart() } };
78: }
79: 
