82: const server = createServer(async (req, res) => {
83:   const url = new URL(req.url, `http://localhost:${PORT}`);
84:   try {
85:     if (req.method === "GET" && url.pathname === "/api/products") {
86:       return sendJson(res, 200, { products: PRODUCTS });
87:     }
88:     if (req.method === "GET" && url.pathname === "/api/search") {
89:       const query = url.searchParams.get("q") ?? "";
90:       const readPrice = (name) => {
91:         const raw = url.searchParams.get(name);
92:         return raw === null || raw === "" ? null : Number(raw);
93:       };
94:       const { results, facets } = searchProducts(query, {
95:         minPrice: readPrice("minPrice"),
96:         maxPrice: readPrice("maxPrice"),
97:       });
98:       return sendJson(res, 200, { query, results, facets });
99:     }
100:     if (req.method === "GET" && url.pathname === "/api/cart") {
101:       return sendJson(res, 200, { cart: serializeCart() });
102:     }
103:     if (req.method === "POST" && url.pathname === "/api/cart/add") {
104:       const { productId } = await readJsonBody(req);
105:       if (!PRODUCTS.some((p) => p.id === productId)) {
106:         return sendJson(res, 400, { error: "Unknown product" });
107:       }
108:       const line = cart.items.find((item) => item.productId === productId);
109:       if (line) {
110:         line.quantity += 1;
111:       } else {
112:         cart.items.push({ productId, quantity: 1 });
113:       }
114:       return sendJson(res, 200, { cart: serializeCart() });
115:     }
116:     if (req.method === "POST" && url.pathname === "/api/coupon") {
117:       const { code } = await readJsonBody(req);
118:       const result = applyCoupon(code);
119:       return sendJson(res, result.status, result.body);
120:     }
121:     if (req.method === "GET") {
122:       return serveStatic(res, PUBLIC_DIR, url.pathname);
123:     }
124:     sendJson(res, 405, { error: "Method not allowed" });
125:   } catch (error) {
126:     console.error(`[acme-shop] ${req.method} ${url.pathname} failed:`, error);
127:     sendJson(res, 500, { error: "Internal Server Error" });
128:   }
129: });
130: 
